    abstract:     'Servicio de Mapas WEB de ArcGIS Server 10.2, elaborado en conjunto entre la Dirección General de Aguas y la Dirección General de Obras Públicas, ambas del Ministerio de Obras Públicas.\nEl Servicio web contiene las Estaciones Fluviométricas simbolizadas de acuerdo a los niveles de alertas que se generan por la variación de los caudales de los principales ríos de Chile. Estás estaciones registran los niveles de los caudales y los reportan a través de señal satelital a un servidor ubicado en el edificio ministerial en Santiago, donde se procesan y se transforman en una aplicación web de monitoreo.\nLas lecturas tienen una actualización diferenciada por estaciones, que fluctúa entre 15 a 60 minutos, en promedio se considera la actualización o refresco de los datos cada 30 minutos.\n',
