    abstract:     'Polígonos que representan a las turberas de la Región de Magallanes y Antártica Chilena.\n\nDEFINICIÓN TURBERA: Son un tipo de humedal donde se produce y acumula progresivamente materia orgánica muerta que proviene de plantas adaptadas a vivir en sitios inundados de agua, con un bajo contenido de oxígeno y escasa disponibilidad de nutrientes.\n\nPRIORIDAD n°1: Turberas en áreas colocadas bajo protección oficial (SNASPE, SP, BNP, ZOIT)\n\nGEOMETRIA: Corresponde a Polígonos,\n\nCOBERTURA: Región de Magallanes y Antártica Chilena.\n\nFUENTE: Análisis en SIG por parte del Departamento de Conservación y Protección de Recursos Hídricos. DCPRH. DGA. Inventario Nacional de Humedales (INH) del Ministerio de Medio ambiente (MMA)\n\nESCALA: 1:50.000 y 1:250.000\n\nESCALA MAXIMA \\ \nRANGO DE ESCALA: La que el Usuario estime.\n\nTIPO DE LEVANTAMIENTO: Cartografía IGM 1:50.000, Cartografía 1:250.000\n\nSISTEMA DE REFERENCIA: Sirgas Chile. Coordenadas Geográficas.\n\nACTUALIZACION DE LOS DATOS: Capa estática, sin actualizaciones programadas.\n\nULTIMA ACTUALIZACIÓN: noviembre 2023\n\nSIMBOLOGIA OFICIAL: No tiene.\n\nRESPONSABLE DE LA ACTUALIZACIÓN: Departamento de Conservación y Protección de Recursos Hídricos. DCPRH. DGA.\n\nEN CASO DE ERRORES, COMUNICARSE CON: Cartógrafo, División de Estudios y Planificación: Guillermo Tapia Molina; mail: guillermo.tapia.m@mop.gov.cl\n\nEN CASO DE CONSULTAS COMUNICARSE CON: Cartógrafo, División de Estudios y Planificación: Guillermo Tapia Molina; mail: guillermo.tapia.m@mop.gov.cl\n\nLIMITACIONES DE USO: Información de Uso Libre.\n',
