    abstract:     'Tipo de Cobertura: Puntual de tipo Naciona lFuente: La información que fue levantada por personal de la Subdirección de Servicios Sanitarios Rurales donde corresponde a levantamiento georreferenciado con el Sistema Global de Navegación por Satélite GNSS (métrico) de los estanques, oficina o localidad beneficiada, o trazado en Google Earth o similar.Tipo de levantamiento: Sistema Global de Navegación por Satélite GNSS (submétrico, métrico) o trazado en Google Earth o similar, para los casos en que no haya levantamiento GNSS.Escala máxima: 1:5.000 a 1:20.00.000. Sistema de Referencia: SIRGAS CHILE. Coordenadas Geodésicas. Actualización de los datos: Estos archivos son considerados documentos de trabajo y corresponden a Bases de Datos dinámicas que están en constante depuración, complementación y actualización. Por lo cual se puede considerar como la última información disponible.Simbología oficial: No existe simbología oficialResponsable de la actualización: Francisco Oses Solis (DOH) <francisco.oses@mop.gov.cl> Analista Unidad de Gestión de Información Territorial,Belén Rojas Martínez (DOH) <belen.rojas@mop.gov.cl> Analista de estudios SSR En caso de consultas de la información comunicarse con: Francisco Oses <francisco.oses@mop.gov.cl> Acontinuación se detalla la lista de campos y su descripción correspondiente:Campos Descripción:ID_IDECódigo único identificador del Servicio Sanitario Rural NOMBRENombre del Servicio Sanitario Rural MXSITEIDCódigo de uso interno del MAXIMO, que es el sistema que interopera la información alfanumérica con la espacial.COD_REGIndica el código de la Región en MAXIMO donde está el Servicio Sanitario Rural COD_COMIndica el código de la Provincia en MAXIMO donde está el Servicio Sanitario Rural COD_PROVIndica el código de la Comuna en MAXIMO donde está el Servicio Sanitario Rural REGIONIndica el nombre de la Región donde está el Servicio Sanitario Rural PROVINCIAIndica el nombre de la Provincia donde está el Servicio Sanitario Rural COMUNAIndica el nombre de la Comuna donde está el Servicio Sanitario Rural FUENTEUnidad o Departamento de donde se genera el dato.FECHA_ACTUALIZACIONFecha de actualización de la geometría.LEVANTAMIENTOTipo de levantamiento del dato geográfico.* MAXIMO: Corresponde a un sistema informático para la gestión de activos diseñado por IBM implementado en el Ministerio de Obras Públicas con el cual interopera la información Geográfica de los modelos de datos de la IDE MOP.',
