    tituloUIEn: 'National Census Plan 2024–2025 of Chile',
    tituloUIPt: 'Plano Nacional de Censos 2024–2025 do Chile',
    abstract:     'Cobertura de puntos que representan la ubicación y descripción de los Puntos Censales ubicados a lo largo de todo el país. Esta información se enmarca en el Plan Nacional de Censo Vial (PNCV), el cual, entrega información relacionada con el flujo vehicular de la red vial interurbana y rural que está bajo la tuición de la Dirección de Vialidad. La información disponible permite construir o complementar matrices de viaje, y constituyen un insumo para analizar las condiciones de operación y definir políticas de planificación de la red, como diseño, mantenimiento, explotación, mejoramiento y construcción de caminos.\nLos datos son recopilados durante los años impares en la zona Norte (Arica y Parinacota hasta O’Higgins) y durante los años pares en la zona Sur (Maule hasta Magallanes). Cada año se contemplan tres muestras: en febrero (verano), en junio (invierno) y en octubre (primavera).\nActualmente, se han realizado los levantamientos de información del año 2025 para la zona Norte y año 2024 para la zona Sur.',
